(7161108, 1099102, 118154, '<td valign="top">Very nice image no doubt, in my top five for sure.</td>', 'Very nice image no doubt, in my top five for sure.', '2014-01-22 11:52:37.000000', NULL, 1),
(7161110, 1099423, 118154, '<td valign="top">My winner, wonderful in most every way.10.</td>', 'My winner, wonderful in most every way.10.', '2014-01-22 11:55:23.000000', NULL, 1),
