(7161243, 1099345, 59029, '<td valign="top">A few too many competing elements - the font made up of crows, the main crow and then the face in the bottom right.</td>', 'A few too many competing elements - the font made up of crows, the main crow and then the face in the bottom right.', '2014-01-22 18:01:13.000000', NULL, 1),
(7161246, 1099153, 59029, '<td valign="top">sorry but too many different fonts, all rendered differently, detract from the first rule of design and photography: One dominant element, not several inferior ones.</td>', 'sorry but too many different fonts, all rendered differently, detract from the first rule of design and photography: One dominant element, not several inferior ones.', '2014-01-22 18:03:09.000000', NULL, 1),
