(7161568, 1099405, 173844, '<td valign="top">Excellent, elegant image, perfectly complemented by the graphics.  Really sings.</td>', 'Excellent, elegant image, perfectly complemented by the graphics.  Really sings.', '2014-01-23 15:26:50.000000', NULL, 1),
(7161571, 1099069, 173844, '<td valign="top">Brilliant picture for an album cover.  As close as can be to neon without frazzling your eyes.</td>', 'Brilliant picture for an album cover.  As close as can be to neon without frazzling your eyes.', '2014-01-23 15:32:32.000000', NULL, 1),
(7161575, 1099129, 173844, '<td valign="top">Incredible image.  Is this photography?  I''m asking only because I sense limitations -- of my own making -- being shattered.  Simple enumeration of all the wonderful elements here seems pedantic, so I''ll mention just two that I appreciate --  the serpentine harpoon with the golden point and the whale''s eye that looks like a globe.  A favorite.</td>', 'Incredible image.  Is this photography?  I''m asking only because I sense limitations -- of my own making -- being shattered.  Simple enumeration of all the wonderful elements here seems pedantic, so I''ll mention just two that I appreciate --  the serpentine harpoon with the golden point and the whale''s eye that looks like a globe.  A favorite.', '2014-01-23 15:47:04.000000', NULL, 1),
(7161579, 1099025, 173844, '<td valign="top">Gorgeous image.  The composition has a fine intuitive balance.  Great textures and sublime colors.  Should fly off the shelves.</td>', 'Gorgeous image.  The composition has a fine intuitive balance.  Great textures and sublime colors.  Should fly off the shelves.', '2014-01-23 16:08:03.000000', NULL, 1),
